def rabin_karp_search(pattern, text):
    import hashlib
    from collections import defaultdict

    MOD = 10**9 + 7
    BASE = 29

    class HashCalculator:
        def __init__(self, base, mod, pattern):
            self.base = base
            self.mod = mod
            self.base_pw = [1] * (len(pattern) + 1)
            self.h_pattern = 0
            for i, char in enumerate(pattern):
                self.h_pattern = (self.h_pattern * base + ord(char)) % mod
                self.base_pw[i + 1] = self.base_pw[i] * base % mod

        def hash_of(self, s):
            h_s = 0
            for i, char in enumerate(s):
                h_s = (h_s * self.base + ord(char)) % self.mod
            return h_s

        def sliding_hash(self, start):
            return (self.h_pattern - self.base_pw[len(pattern)] * self.hash_of(pattern[:start]) % self.mod) % self.mod

    if len(pattern) > len(text):
        return -1

    hash_calculator = HashCalculator(BASE, MOD, pattern)
    h_text = hash_calculator.hash_of(text[:len(pattern)])

    if h_text == hash_calculator.h_pattern:
        return 0 if pattern == text[:len(pattern)] else -1

    for i in range(1, len(text) - len(pattern) + 1):
        if h_text == hash_calculator.sliding_hash(i):
            return i

    return -1

